// iPhone home-screen icons. Existing logos; generated PNGs, 2026-09-05.
const ICONS = {"bhub":{"32":"","180":"","192":"","512":""},"crm":{"32":"","180":"","192":"","512":""},"dashboard":{"32":"","180":"","192":"","512":""},"demos":{"32":"","180":"","192":"","512":""}};
const LABELS = {dashboard:"Dashboard",demos:"Demonstrações",bhub:"Briefing Hub",crm:"ImobiBoard"};
export function makeIconWorker(base, family) {
 return {
  ...base,
  async fetch(request, env, ctx) {
   const url = new URL(request.url), path = url.pathname;
   const name = family === "dashboard" ? (/^\/briefing-hub-demo(?:\.html)?\/?$/.test(path) ? "bhub" : /^\/demos\/?$/.test(path) ? "demos" : "dashboard") : family;
   const match = path.match(/^\/app-icons\/v20260905\/(dashboard|demos|bhub|crm)-(32|180|192|512)\.png$/);
   if (match || path === "/apple-touch-icon.png" || path === "/apple-touch-icon-precomposed.png") {
    if (!["GET","HEAD"].includes(request.method)) return new Response(null,{status:405,headers:{Allow:"GET, HEAD"}});
    const png=ICONS[match ? match[1] : name][match ? match[2] : 180];
    const data=Uint8Array.from(atob(png),c=>c.charCodeAt(0));
    return new Response(request.method==="HEAD"?null:data,{headers:{"content-type":"image/png","content-length":String(data.length),"cache-control":"public, max-age=31536000, immutable","x-content-type-options":"nosniff"}});
   }
   const response = await base.fetch(request, env, ctx);
   if (family==="crm" && path==="/manifest.webmanifest" && response.ok) {
    const original=await response.clone().json().catch(()=>null);
    if (original) {
     const manifest={...original,icons:[192,512].map(size=>({src:"/app-icons/v20260905/crm-"+size+".png",sizes:size+"x"+size,type:"image/png",purpose:"any"}))};
     const headers=new Headers(response.headers); headers.delete("content-length");headers.delete("etag");headers.delete("content-encoding");headers.set("content-type","application/manifest+json");headers.set("cache-control","no-cache");
     return new Response(JSON.stringify(manifest),{status:response.status,headers});
    }
   }
   if (!response.ok || !["GET"].includes(request.method) || !(response.headers.get("content-type")||"").includes("text/html") || path.startsWith("/api/")) return response;
   const href="/app-icons/v20260905/"+name;
   const tags='<link rel="apple-touch-icon" sizes="180x180" href="'+href+'-180.png"><link rel="icon" type="image/png" sizes="32x32" href="'+href+'-32.png"><meta name="apple-mobile-web-app-title" content="'+LABELS[name]+'"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">';
   const headers=new Headers(response.headers);
   headers.delete("content-length");headers.delete("etag");headers.delete("content-encoding");
   const input=new Response(response.body,{status:response.status,statusText:response.statusText,headers});
   return new HTMLRewriter()
    .on('link', {element(el){const rel=(el.getAttribute("rel")||"").toLowerCase().split(/\s+/);if(rel.some(v=>["icon","apple-touch-icon","apple-touch-icon-precomposed"].includes(v))) el.remove();}})
    .on('meta[name="apple-mobile-web-app-title"]',{element(el){el.remove();}})
    .on('head',{element(el){el.append(tags,{html:true});}})
    .transform(input);
  }
 };
}
